        return -1 if v < 0 else (1 if v > 0 else 0)

    def as_pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return (v[0], v[1])
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def move_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def move_away(src, dst):
        return [clamp_step(src[0] - dst[0]), clamp_step(src[1] - dst[1])]

    def valid_point(p):
        return isinstance(p, (list, tuple)) and len(p) >= 2

    def extract_points(v):
        pts = []
        if isinstance(v, (list, tuple)):
            for it in v:
                if valid_point(it):
                    pts.append((it[0], it[1]))
        return pts

    def best_by_score(src, pts, fn):
        best = None
        best_score = None
        for p in pts:
            s = fn(src, p)
            if best is None or s < best_score:
                best = p
                best_score = s
        return best

    def farthest_point(src, pts):
        best = None
        best_score = None
        for p in pts:
            s = manhattan(src, p)
            if best is None or s > best_score:
                best = p
                best_score = s
        return best

    env = observation.get("environment_name", "resource_collection")
    sx, sy = as_pos(observation.get("self_position"), (0, 0))
    self_pos = (sx, sy)
    opp_pos = as_pos(observation.get("opponent_position"), self_pos)
    gw = observation.get("grid_width", 0) or 0
    gh = observation.get("grid_height", 0) or 0
    maxx = gw - 1 if gw and gw > 0 else 0
    maxy = gh - 1 if gh and gh > 0 else 0

    resources = extract_points(observation.get("resources") or observation.get("resource_positions") or observation.get("resource_cells"))
    unclaimed = extract_points(observation.get("unclaimed_cells") or observation.get("territory_targets") or observation.get("neutral_cells"))
    opponent_territory = extract_points(observation.get("opponent_territory") or observation.get("enemy_territory"))
    own_territory = extract_points(observation.get("own_territory") or observation.get("self_territory"))

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            if valid_point(opp_pos):
                return move_toward(self_pos, opp_pos)
            if resources:
                t = best_by_score(self_pos, resources, manhattan)
                return move_toward(self_pos, t)
            return [0, 0]
        corners = [(0, 0), (0, maxy), (maxx, 0), (maxx, maxy)]
        if valid_point(opp_pos):
            away_corner = farthest_point(opp_pos, corners)
            if away_corner is not None:
                return move_toward(self_pos, away_corner)
            return move_away(self_pos, opp_pos)
        return [0, 0]

    if env == "territory_control":
        if unclaimed:
            t = best_by_score(self_pos, unclaimed, manhattan)
            if t is not None:
                return move_toward(self_pos, t)
        if opponent_territory:
            t = best_by_score(self_pos, opponent_territory, manhattan)
            if t is not None:
                return move_toward(self_pos, t)
        if valid_point(opp_pos):
            return move_toward(self_pos, opp_pos)
        if own_territory:
            # Slight outward drift from our own cluster if no expansion target is visible.
            far = farthest_point(self_pos, own_territory)
            if far is not None:
                return move_away(self_pos, far)
        return [0, 0]

    # resource_collection and fallback
    if resources:
        if valid_point(opp_pos):
            # Prefer resources we can reach no later than the opponent.
            best = None
            best_score = None
            for r in resources:
                ds = manhattan(self_pos, r)
                do = manhattan(opp_pos, r)
                score = ds * 2 - do
                if best is None or score < best_score:
                    best = r
                    best_score = score
            if best is not None:
                return move_toward(self_pos, best)
        t = best_by_score(self_pos, resources, manhattan)
        if t is not None:
            return move_toward(self_pos, t)

    if valid_point(opp_pos):
        # Deny/pressure when no resources are immediately available.
        if resources or unclaimed or opponent_territory:
            return move_toward(self_pos, opp_pos)
        return move_away(self_pos, opp_pos)

    return [0, 0]

